-- ----------------------------
-- Table structure for request_log
-- ----------------------------
DROP TABLE IF EXISTS `request_log`;
CREATE TABLE `request_log`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'log id, for example log_xxx',
  `request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'request trace id',
  `user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'request user id, null for anonymous/login failures',
  `interface_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'controller or handler method name',
  `method` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'HTTP method',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'request path',
  `input_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'masked request params/body snapshot',
  `output_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'masked response/error snapshot',
  `cost_time` bigint NOT NULL COMMENT 'cost time in ms',
  `is_slow` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'slow request flag',
  `http_status` int NULL DEFAULT NULL COMMENT 'HTTP status code',
  `success` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'success flag',
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'business error code',
  `client_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'client ip',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'created time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_request_log_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_request_log_user_time`(`user_id` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_request_log_request_id`(`request_id` ASC) USING BTREE,
  INDEX `idx_request_log_path_method`(`path` ASC, `method` ASC) USING BTREE,
  INDEX `idx_request_log_slow_success`(`is_slow` ASC, `success` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'request log table' ROW_FORMAT = Dynamic;

